    <script>
        class DeepResearchApp {
            constructor() {
                this.models = {
                    cerebras: { name: 'Cerebras GPT-OSS', maxTokens: 65000 },
                    grok4: { name: 'Grok-4', maxTokens: 256000 },
                    grok4fast: { name: 'Grok-4-Fast', maxTokens: 256000 },
                    qwen: { name: 'Qwen 2.5 Max', maxTokens: 131000 }
                };
                this.exa = { maxResults: 100 };
                this.initializeApp();
            }

            initializeApp() {
                this.bindEvents();
                this.initializeViewTransitions();
            }

            bindEvents() {
                // Mode selector
                document.querySelectorAll('.mode-btn').forEach(btn => {
                    btn.addEventListener('click', (e) => {
                        this.switchMode(e.target.dataset.mode);
                        this.hapticFeedback(e.target);
                    });
                });

                // Search button
                document.querySelector('.search-btn').addEventListener('click', () => {
                    this.startResearch();
                });

                // Enter key support
                document.querySelector('.search-input').addEventListener('keydown', (e) => {
                    if (e.key === 'Enter' && e.ctrlKey) {
                        this.startResearch();
                    }
                });
            }

            initializeViewTransitions() {
                // Modern SPA navigation with View Transitions API
                if ('startViewTransition' in document) {
                    this.viewTransitions = true;
                }
            }

            switchMode(mode) {
                document.querySelectorAll('.mode-btn').forEach(btn => {
                    btn.classList.toggle('active', btn.dataset.mode === mode);
                });

                // Update UI based on mode
                if (mode === 'deep') {
                    this.showAdvancedOptions();
                }
            }

            async startResearch() {
                const query = document.querySelector('.search-input').value;
                if (!query.trim()) return;

                this.showProgress();

                try {
                    await this.executeResearchPipeline(query);
                } catch (error) {
                    this.handleError(error);
                }
            }

            async executeResearchPipeline(query) {
                // Stage 1: Planning with Cerebras
                await this.updateStep(0, 'active');
                const plan = await this.callCerebras({
                    prompt: `Készíts részletes kutatási tervet: ${query}`,
                    max_tokens: 2000
                });
                await this.updateStep(0, 'completed');

                // Stage 2: Source gathering with Exa
                await this.updateStep(1, 'active');
                const sources = await this.callExa({
                    query: query,
                    num_results: 100,
                    type: 'auto',
                    livecrawl: 'always'
                });
                await this.updateStep(1, 'completed');

                // Stage 3: Analysis with Grok-4 and Qwen in parallel
                await this.updateStep(2, 'active');
                const [grokAnalysis, qwenAnalysis] = await Promise.all([
                    this.callGrok4({
                        messages: [{ role: 'user', content: `Elemezd: ${JSON.stringify(sources)}` }],
                        max_tokens: 4000
                    }),
                    this.callQwen({
                        messages: [{ role: 'user', content: `Szintetizáld: ${JSON.stringify(sources)}` }],
                        max_tokens: 4000
                    })
                ]);
                await this.updateStep(2, 'completed');

                // Stage 4: Report generation
                await this.updateStep(3, 'active');
                const report = await this.generateReport({
                    plan, sources, grokAnalysis, qwenAnalysis
                });
                await this.updateStep(3, 'completed');

                this.displayResults(report);
            }

            async callCerebras(params) {
                const response = await fetch('https://api.cerebras.ai/v1/chat/completions', {
                    method: 'POST',
                    headers: {
                        'Authorization': `Bearer ${CEREBRAS_API_KEY}`,
                        'Content-Type': 'application/json'
                    },
                    body: JSON.stringify({
                        model: 'gpt-oss-120b',
                        messages: [{ role: 'user', content: params.prompt }],
                        max_tokens: params.max_tokens,
                        temperature: 0.7
                    })
                });
                return await response.json();
            }

            async callGrok4(params) {
                const response = await fetch('https://api.x.ai/v1/chat/completions', {
                    method: 'POST',
                    headers: {
                        'Authorization': `Bearer ${GROK_API_KEY}`,
                        'Content-Type': 'application/json'
                    },
                    body: JSON.stringify({
                        model: 'grok-4',
                        messages: params.messages,
                        max_tokens: params.max_tokens,
                        temperature: 0.8
                    })
                });
                return await response.json();
            }

            async callQwen(params) {
                const response = await fetch('https://dashscope-intl.aliyuncs.com/compatible-mode/v1/chat/completions', {
                    method: 'POST',
                    headers: {
                        'Authorization': `Bearer ${QWEN_API_KEY}`,
                        'Content-Type': 'application/json'
                    },
                    body: JSON.stringify({
                        model: 'qwen-max-2025-01-25',
                        messages: params.messages,
                        max_tokens: params.max_tokens
                    })
                });
                return await response.json();
            }

            async callExa(params) {
                const response = await fetch('https://api.exa.ai/search', {
                    method: 'POST',
                    headers: {
                        'x-api-key': EXA_API_KEY,
                        'Content-Type': 'application/json'
                    },
                    body: JSON.stringify(params)
                });
                return await response.json();
            }

            async generateReport(data) {
                // Use Grok-4 for final report generation
                return await this.callGrok4({
                    messages: [{
                        role: 'user',
                        content: `20+ oldalas jelentés készítése: ${JSON.stringify(data)}`
                    }],
                    max_tokens: 20000
                });
            }

            showProgress() {
                if (this.viewTransitions) {
                    document.startViewTransition(() => {
                        document.querySelector('.search-container').style.display = 'none';
                        document.querySelector('.research-progress').style.display = 'block';
                    });
                } else {
                    document.querySelector('.search-container').style.display = 'none';
                    document.querySelector('.research-progress').style.display = 'block';
                }
            }

            async updateStep(stepIndex, status) {
                const step = document.querySelectorAll('.step')[stepIndex];
                step.classList.add(status);
                await new Promise(resolve => setTimeout(resolve, 1000));
            }

            displayResults(report) {
                if (this.viewTransitions) {
                    document.startViewTransition(() => {
                        document.querySelector('.research-progress').style.display = 'none';
                        document.querySelector('.results-container').style.display = 'block';
                    });
                } else {
                    document.querySelector('.research-progress').style.display = 'none';
                    document.querySelector('.results-container').style.display = 'block';
                }

                // Animate results sections
                document.querySelectorAll('.report-section').forEach((section, index) => {
                    setTimeout(() => {
                        section.classList.add('visible');
                    }, index * 200);
                });
            }

            hapticFeedback(element) {
                // Visual haptic feedback simulation
                element.style.transform = 'scale(0.95)';
                setTimeout(() => {
                    element.style.transform = 'scale(1)';
                }, 150);

                // Actual haptic feedback on supported devices
                if ('vibrate' in navigator) {
                    navigator.vibrate(10);
                }
            }

            handleError(error) {
                console.error('Research error:', error);
                // Show user-friendly error message
            }
        }

        // Initialize app when DOM is loaded
        document.addEventListener('DOMContentLoaded', () => {
            new DeepResearchApp();
        });

        // API Keys (use environment variables in production)
        const CEREBRAS_API_KEY = 'your-cerebras-key';
        const GROK_API_KEY = 'your-grok-key';
        const QWEN_API_KEY = 'your-qwen-key';
        const EXA_API_KEY = 'your-exa-key';
    </script>
