        if (mode === 'simple') {
            // 100 eredmény egy lépésben
            searches.push(await this.exaSearch(query, 100));
        } else {
            // Mély mód: több kör, különböző megközelítések
            const approaches = [
                `${query} research papers`,
                `${query} latest developments 2025`,
                `${query} industry analysis`,
                `${query} technical documentation`,
                `${query} case studies`
            ];

            for (const approach of approaches) {
                searches.push(await this.exaSearch(approach, 100));
                await this.rateLimitDelay();
            }
        }

        return this.deduplicateResults(searches.flat());
    }

    async exaSearch(query, numResults = 100) {
        return await fetch('https://api.exa.ai/search', {
            method: 'POST',
            headers: {
                'x-api-key': EXA_API_KEY,
                'Content-Type': 'application/json'
            },
            body: JSON.stringify({
                query: query,
                num_results: numResults,
                type: 'auto',  // Neural + keyword hybrid
                livecrawl: 'always',  // Real-time frissesség
                contents: {
                    text: { max_characters: 5000 },
                    summary: true
                },
                use_autoprompt: true
            })
        }).then(r => r.json());
    }

    async rateLimitDelay() {
        // Exa rate limitek tiszteletben tartása
        await new Promise(resolve => setTimeout(resolve, 1000));
    }
}


